#include <stdint.h>

uint16_t pack_voltage_mV(uint16_t cell_mV, uint8_t series_count)
{
    uint16_t total_mV = cell_mV * series_count;
    return total_mV;
}

#include <stdint.h>

/* current_q8 is Q8.8 amperes; valid range is -8192..8192. */
int16_t current_q8_to_mA(int16_t current_q8)
{
    return (int16_t)(current_q8 / 256) * 1000;
}
